use kernel_core::{level::prepare_domain,model::{parse_q,Expr,Model,Q,Row,Var,MAX_Q_BITS},verify::Limits};
use num_bigint::BigInt;
use serde::Deserialize;
fn q(s:&str)->Q{parse_q(s).unwrap()}
fn e(c:&str,t:&[(u32,&str)])->Expr{Expr{constant:q(c),terms:t.iter().map(|(i,c)|(*i,q(c))).collect()}}
fn input()->Model{Model{name:"actual_input".into(),vars:vec![Var{name:"x".into(),integer:false,lower:Some(q("-3")),upper:Some(q("4"))},Var{name:"y".into(),integer:true,lower:Some(q("-2")),upper:Some(q("3"))}],rows:vec![Row{name:"range".into(),expr:e("2/3",&[(0,"2"),(1,"-1")]),lower:Some(q("-2")),upper:Some(q("5"))}],objective:e("-5/7",&[(0,"-2/3"),(1,"11/5")])}}
fn eval(e:&Expr,x:&[Q])->Q{e.terms.iter().fold(e.constant.clone(),|s,(i,a)|s+a*&x[*i as usize])}
fn feasible(m:&Model,x:&[Q])->bool{m.vars.iter().zip(x).all(|(v,x)|v.lower.as_ref().is_none_or(|l|x>=l)&&v.upper.as_ref().is_none_or(|u|x<=u)&&(!v.integer||x.is_integer()))&&m.rows.iter().all(|r|{let z=eval(&r.expr,x);r.lower.as_ref().is_none_or(|l|&z>=l)&&r.upper.as_ref().is_none_or(|u|&z<=u)})}
#[test]fn original_model_prefix_and_full_objective_constant_are_preserved(){let m=input();let d=prepare_domain(&m,&q("13/11"),&Limits::default()).unwrap();assert_eq!(d.equality_row,1);assert_eq!(d.model.vars,m.vars);assert_eq!(d.model.rows[..1],m.rows);assert_eq!(d.model.objective,m.objective);assert_eq!(d.model.name,m.name);assert_eq!(d.model.rows[1].expr,m.objective);assert_eq!(d.model.rows[1].lower,Some(q("13/11")));assert_eq!(d.model.rows[1].upper,Some(q("13/11")));assert_eq!(d.statistics.generated_rows,1);assert_eq!(d.statistics.generated_terms,2);}
#[derive(Deserialize)]struct Point{values:Vec<String>,objective:String,original:bool,restricted:bool}
#[derive(Deserialize)]struct Case{objective:Expr,level:String,points:Vec<Point>}
#[derive(Deserialize)]struct Oracle{cases:Vec<Case>}
#[test]fn independent_fraction_domains_include_empty_constant_and_fractional_levels(){let oracle:Oracle=serde_json::from_str(include_str!("../../../tests/vectors/level_oracle.json")).unwrap();assert_eq!(oracle.cases.len(),25);let mut count=0;for c in oracle.cases{let mut m=input();m.objective=c.objective;let d=prepare_domain(&m,&q(&c.level),&Limits::default()).unwrap();for p in c.points{let x=p.values.iter().map(|s|q(s)).collect::<Vec<_>>();assert_eq!(eval(&m.objective,&x),q(&p.objective));assert_eq!(feasible(&m,&x),p.original);assert_eq!(feasible(&d.model,&x),p.restricted);count+=1;}}assert_eq!(count,5525);}
#[test]fn names_are_fresh_and_contradictory_domains_are_not_repaired(){let mut m=input();m.rows[0].name="$rpx_level_row_1".into();m.vars[0].lower=Some(q("5"));m.vars[0].upper=Some(q("4"));let d=prepare_domain(&m,&q("0"),&Limits::default()).unwrap();assert_eq!(d.model.vars,m.vars);assert_eq!(d.model.rows[0],m.rows[0]);assert_eq!(d.model.rows[1].name,"$rpx_level_row_2");assert!(!feasible(&d.model,&[q("4"),q("0")]));}
#[test]fn exact_bit_canonical_and_shared_work_limits(){let m=input();assert!(prepare_domain(&m,&Q::new_raw(2.into(),2.into()),&Limits::default()).is_err());let full=prepare_domain(&m,&q("0"),&Limits::default()).unwrap();assert!(prepare_domain(&m,&q("0"),&Limits{work:full.statistics.work-1,..Limits::default()}).unwrap_err().starts_with("RESOURCE_LIMIT"));assert!(prepare_domain(&m,&q("0"),&Limits{work:full.statistics.work,..Limits::default()}).is_ok());let mut bad=m.clone();bad.objective.terms.push((0,q("1")));assert!(prepare_domain(&bad,&q("0"),&Limits::default()).is_err());let huge=Q::from_integer((BigInt::from(1)<<(MAX_Q_BITS as usize))-1);let mut big=m;big.objective=e("0",&[]);big.objective.constant=huge.clone();assert!(prepare_domain(&big,&-huge,&Limits::default()).unwrap_err().starts_with("RESOURCE_LIMIT"));}
#[test]fn zero_coordinate_constant_model_and_normalized_maximization(){let m=Model{name:"constant".into(),vars:vec![],rows:vec![],objective:e("-7/3",&[])};let yes=prepare_domain(&m,&q("-7/3"),&Limits::default()).unwrap();let no=prepare_domain(&m,&q("7/3"),&Limits::default()).unwrap();assert!(feasible(&yes.model,&[]));assert!(!feasible(&no.model,&[]));let max=kernel_core::model::parse_mps("NAME MAXIMUM\nOBJSENSE\n MAX\nROWS\n N OBJ\nCOLUMNS\n X OBJ 2\nRHS\n RHS OBJ -3\nBOUNDS\n LO B X -2\n UP B X 4\nENDATA\n").unwrap();assert_eq!(max.objective,e("-3",&[(0,"-2")]));let restricted=prepare_domain(&max,&q("-5"),&Limits::default()).unwrap();assert!(feasible(&restricted.model,&[q("1")]));assert!(!feasible(&restricted.model,&[q("-1")]));}
